-- ─────────────────────────────────────────────────────────────
-- BAS Categories & Tenant Preferences
-- ─────────────────────────────────────────────────────────────
--
-- BAS (Bokföringsplanen för Aktiebolag) is the standard Swedish chart of accounts.
-- bas_categories: Shared app-level reference table (~472 three-digit account groups).
--   - NO RLS: Data is non-sensitive, publicly available from bas.se, identical for all tenants.
--   - Immutable: Rules block INSERT/UPDATE/DELETE by app role. Data only changes yearly via new migration.
--   - How to update yearly: Download new XLSX from bas.se, re-run parse-bas.mjs, diff, create additive migration.
--
-- tenant_bas_preferences: Per-tenant activation, favorites, aliases, and custom translations.
--   - Full RLS with tenant isolation policy.
--   - Follows mandatory template (id, tenantId, createdAt, updatedAt, createdBy, source).
-- ─────────────────────────────────────────────────────────────

-- ============================================================
-- PART 1: bas_categories — shared reference table (no RLS)
-- ============================================================

CREATE TABLE "bas_categories" (
    "code" VARCHAR(4) NOT NULL,
    "name" TEXT NOT NULL,
    "name_en" TEXT,
    "name_fr" TEXT,
    "class_name" TEXT NOT NULL,
    "class_num" INTEGER NOT NULL,
    "is_common" BOOLEAN NOT NULL DEFAULT false,
    "suggested_alias" VARCHAR(10),
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT "bas_categories_pkey" PRIMARY KEY ("code")
);

-- Immutability: silently drop UPDATE/DELETE (same pattern as audit_logs)
CREATE RULE no_update_bas AS ON UPDATE TO bas_categories DO INSTEAD NOTHING;
CREATE RULE no_delete_bas AS ON DELETE TO bas_categories DO INSTEAD NOTHING;

-- SELECT-only grant — no write permissions for app role
GRANT SELECT ON TABLE bas_categories TO defterfab_app;

-- ============================================================
-- PART 2: Seed BAS categories (~472 entries)
-- ============================================================

-- BAS categories seed data
-- Generated from BAS kontoplan 2026 (Swedish) + BAS 2025 (English) + AI French translations
-- Total entries: 472


-- ============================================================
-- PART 3: tenant_bas_preferences — per-tenant preferences (full RLS)
-- ============================================================

CREATE TABLE "tenant_bas_preferences" (
    "id" UUID NOT NULL DEFAULT gen_random_uuid(),
    "tenant_id" UUID NOT NULL,
    "bas_code" VARCHAR(4) NOT NULL,
    "is_favorite" BOOLEAN NOT NULL DEFAULT false,
    "short_code" VARCHAR(10),
    "translations" JSONB,
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    "updated_at" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    "created_by" UUID NOT NULL,
    "source" VARCHAR(20) NOT NULL DEFAULT 'web',

    CONSTRAINT "tenant_bas_preferences_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "tenant_bas_preferences_bas_code_fkey" FOREIGN KEY ("bas_code") REFERENCES "bas_categories"("code"),
    CONSTRAINT "tenant_bas_preferences_tenant_id_fkey" FOREIGN KEY ("tenant_id") REFERENCES "tenants"("id") ON DELETE CASCADE
);

-- Unique constraint: one preference per tenant per BAS code
CREATE UNIQUE INDEX "tenant_bas_preferences_tenant_id_bas_code_key" ON "tenant_bas_preferences"("tenant_id", "bas_code");

-- Query indexes
CREATE INDEX "tenant_bas_preferences_tenant_id_is_favorite_idx" ON "tenant_bas_preferences"("tenant_id", "is_favorite");
CREATE INDEX "tenant_bas_preferences_tenant_id_bas_code_idx" ON "tenant_bas_preferences"("tenant_id", "bas_code");

-- Full CRUD grant for app role
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE tenant_bas_preferences TO defterfab_app;

-- RLS: tenant isolation with both USING and WITH CHECK (matching audit_logs pattern)
ALTER TABLE "tenant_bas_preferences" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "tenant_bas_preferences" FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "tenant_bas_preferences"
  USING (tenant_id = current_setting('app.tenant_id', true)::uuid)
  WITH CHECK (tenant_id = current_setting('app.tenant_id', true)::uuid);
